// src/lib/tradeInput.ts
var CRYPTO_CAP_FRACTION = 0.0001;
function getMaxBuyUnits(opts) {
  const { cash, price } = opts;
  if (!Number.isFinite(price) || price <= 0 || !Number.isFinite(cash)) {
    return { max: 0, cashMax: 0, capLimited: false, reason: null };
  }
  const cashMax = Math.max(0, Math.floor((cash + 0.000000001) / price));
  if (!opts.isCrypto)
    return { max: cashMax, cashMax, capLimited: false, reason: null };
  const capValue = Math.max(0, (opts.portfolioValue ?? 0) * CRYPTO_CAP_FRACTION);
  const room = capValue - (opts.currentCryptoValue ?? 0);
  const capMax = room > 0 ? Math.floor((room + 0.000000001) / price) : 0;
  const max = Math.min(cashMax, capMax);
  const capLimited = capMax < cashMax;
  let reason = null;
  if (capLimited) {
    reason = capMax <= 0 ? `Bitcoin is capped at 0.01% of your portfolio (about $${capValue.toFixed(2)} right now). One coin costs more than that, so you can't buy any yet.` : `Bitcoin is capped at 0.01% of your portfolio, so you can buy at most ${capMax} right now.`;
  }
  return { max, cashMax, capLimited, reason };
}

